import React, { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

import { SectionOrbit, SectionHeader } from '@domains/marketing/shared';
import './trust-section.styles.scss';

gsap.registerPlugin(ScrollTrigger);

interface TrustObject {
  title: string;
  text: string;
  imgSrc: string;
}

const TRUST_OBJECTS: TrustObject[] = [
  {
    title: 'Secure Checkout',
    text: 'Payment managed by Stripe',
    imgSrc: '/images/secure.webp',
  },
  {
    title: 'Instant Access Unlock',
    text: 'Customers access content immediately',
    imgSrc: '/images/access.webp',
  },
  {
    title: 'Revenue Insight',
    text: 'Analytics to grow your business',
    imgSrc: '/images/insight.webp',
  },
  {
    title: 'Creator-Controlled Branding',
    text: 'Your logo, your colors, your decisions',
    imgSrc: '/images/branding.webp',
  },
];

const TrustSection: React.FC = () => {
  const sectionRef = useRef<HTMLDivElement | null>(null);
  const cardsWrapRef = useRef<HTMLDivElement | null>(null);
  // const floatTweensRef = useRef<gsap.core.Tween[]>([]);
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  useEffect(() => {
    if (!sectionRef.current || !cardsWrapRef.current) {
      return;
    }

    const prefersReduced = window.matchMedia?.(
      '(prefers-reduced-motion: reduce)',
    ).matches;
    if (prefersReduced) {
      return;
    }

    const ctx = gsap.context(() => {
      const wrap = cardsWrapRef.current!;
      const cards = gsap.utils.toArray<HTMLElement>(
        wrap.querySelectorAll('.trust-card'),
      );

      // Initial state: 20px lower, invisible
      gsap.set(cards, {
        autoAlpha: 0,
        y: 28,
        willChange: 'transform, opacity',
      });

      const tl = gsap.timeline({ paused: true });

      // One-by-one reveal
      tl.to(cards, {
        autoAlpha: 1,
        y: 0,
        duration: 0.55,
        ease: 'power3.out',
        stagger: 0.12,
        clearProps: 'willChange',
      });

      // Prevent CSS transition conflicts while GSAP runs
      const setRevealing = (on: boolean): void => {
        wrap.classList.toggle('is-revealing', on);
      };

      tl.eventCallback('onStart', () => setRevealing(true));
      tl.eventCallback('onComplete', () => setRevealing(false));
      tl.eventCallback('onReverseComplete', () => setRevealing(false));

      ScrollTrigger.create({
        trigger: sectionRef.current!,
        start: 'top 45%',
        invalidateOnRefresh: true,
        onEnter: () => tl.play(),
        onEnterBack: () => tl.play(),
        onLeaveBack: () => tl.reverse(),
      });
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  return (
    <div className="max-w trust-content" ref={sectionRef}>
      <SectionOrbit />
      <SectionHeader
        className="trust-header"
        title={
          <span>
            Built for <span className="primary-word">Serious</span> Creators
          </span>
        }
        subtitle="Your business deserves a platform that feels powerful and focused"
      />

      <div
        className="trust-cards"
        ref={cardsWrapRef}
        onMouseLeave={() => setActiveIndex(null)}
      >
        {TRUST_OBJECTS.map((t, index) => (
          <div
            key={index}
            className={clsx('trust-card', {
              'is-dimmed': activeIndex !== null && activeIndex !== index,
              'is-active': activeIndex === index,
            })}
            onMouseEnter={() => setActiveIndex(index)}
          >
            <div className="tc-image-wrap">
              {/* energy field (no card background) */}
              <span className="tc-energy" aria-hidden="true" />
              <img className="tc-image" height={70} src={t.imgSrc} alt="" />
            </div>

            <h4 className="tc-header">{t.title}</h4>
            <p className="tc-text">{t.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TrustSection;

@use '../../../../../styles/index.scss' as *;

.trust-content {
  display: flex;
  flex-direction: column;
  align-items: center;

  .trust-header {
    margin: $spacing-7 0 $spacing-5;
  }

  .trust-cards {
    display: flex;
    gap: $spacing-6;
    width: 100%;
    justify-content: space-evenly;
    margin-top: $spacing-7;

    // while GSAP reveals, avoid CSS fighting transforms/opacity
    &.is-revealing .trust-card {
      transition: none !important;
    }

    .trust-card {
      display: flex;
      flex-direction: column;
      text-wrap: wrap;
      text-align: center;
      align-items: center;
      width: 280px;

      position: relative;

      // No background. No borders. Cinematic “floating UI fragments”.
      background: transparent;

      // Hover/interaction transitions (disabled during reveal via .is-revealing)
      transition:
        transform 260ms ease,
        opacity 260ms ease,
        filter 260ms ease;

      // Hover focus base
      opacity: 1;

      .tc-image-wrap {
        position: relative;
        display: grid;
        place-items: center;
        // width: 92px;
        height: 92px;

        // Energy field behind the icon (this is the cinematic part)
        .tc-energy {
          position: absolute;
          inset: 0;
          margin: auto;
          width: 88px;
          height: 88px;
          border-radius: 999px;
          pointer-events: none;
          z-index: 0;

          // layered glow field (no card background required)
          background:
            radial-gradient(
              circle at 30% 30%,
              rgba(58, 201, 219, 0.22) 0%,
              rgba(58, 201, 219, 0.08) 35%,
              transparent 70%
            ),
            radial-gradient(
              circle at 70% 65%,
              rgba(58, 46, 111, 0.22) 0%,
              rgba(58, 46, 111, 0.1) 38%,
              transparent 72%
            );

          filter: blur(4px);
          opacity: 0.55;
          transform: scale(1);
          will-change: transform, opacity;
        }

        .tc-image {
          position: relative;
          z-index: 1;
          transition:
            transform 260ms ease,
            filter 260ms ease;
          will-change: transform, filter;
        }
      }

      .tc-header {
        margin-top: $spacing-4;
        font-family: $font-body;
      }

      .tc-text {
        margin-top: $spacing-1;
        font-size: 12px;
        color: var(--text-secondary);
      }

      // Cinematic hover: minimal lift + icon “energize”
      &:hover {
        transform: translateY(-8px) !important;
        cursor: pointer;

        .tc-image {
          transform: translateY(-2px) scale(1.03);
          filter: drop-shadow(0 10px 18px rgba(58, 201, 219, 0.16))
            drop-shadow(0 12px 34px rgba(58, 46, 111, 0.18))
            drop-shadow(0 10px 26px rgba(255, 189, 65, 0.1));
        }

        .tc-energy {
          opacity: 0.95;
          transform: scale(1.07);
          filter: blur(5px);
        }
      }

      // Dim others when one is hovered (your existing behavior, tuned)
      &.is-dimmed {
        opacity: 0.42;
        filter: saturate(0.92);
        transform: translateY(0);
      }

      &.is-active {
        opacity: 1;
      }
    }
  }
}

.trust-cards.is-revealing .trust-card {
  transition: none !important;
}

